pub const WEBHOOK_KIND: &str = "webhook";

pub const CANARY_ID: &str = "canary";
/// A receiver on the platform's own domain, reached over the same egress as
/// relying parties (PI-STD-014).
pub const CANARY_URL: &str = "https://status-canary.membership-platform.example/webhooks/status";

